package jp.haruto.dreamcamera;
import android.graphics.*;import java.util.Random;
public class PhotoProcessor{
 public static ColorMatrix matrix(Preset p){float sat=1+p.saturation/100f,con=1+p.contrast/100f,exp=(float)Math.pow(2,p.exposure/50f),fade=p.fade*0.45f;ColorMatrix m=new ColorMatrix();m.setSaturation(sat);float r=exp*con*(1+p.red/100f),g=exp*con*(1+p.green/100f),b=exp*con*(1+p.blue/100f);float tr=p.temp*0.7f,ti=p.tint*0.55f,off=128*(1-con)+fade;ColorMatrix c=new ColorMatrix(new float[]{r,0,0,0,off+tr+ti,0,g,0,0,off-ti,0,0,b,0,off-tr,0,0,0,1,0});m.postConcat(c);return m;}
 public static Bitmap apply(Bitmap src,Preset p){Bitmap a=src.copy(Bitmap.Config.ARGB_8888,true),out=Bitmap.createBitmap(a.getWidth(),a.getHeight(),Bitmap.Config.ARGB_8888);Canvas c=new Canvas(out);Paint paint=new Paint(3);paint.setColorFilter(new ColorMatrixColorFilter(matrix(p)));c.drawBitmap(a,0,0,paint);if(p.blur>1)out=blur(out,Math.min(5,Math.max(1,(int)(p.blur/5))));int w=out.getWidth(),h=out.getHeight();int[]px=new int[w*h];out.getPixels(px,0,w,0,0,w,h);Random rnd=new Random(42);float vib=p.vibrance/100f,gr=p.grain/100f,vig=p.vignette/100f,clar=(p.clarity+p.dehaze)/180f;for(int y=0;y<h;y++){float dy=(y-h*.5f)/(h*.5f);for(int x=0;x<w;x++){int i=y*w+x,q=px[i],r=Color.red(q),g=Color.green(q),b=Color.blue(q);float avg=(r+g+b)/3f,mx=Math.max(r,Math.max(g,b)),boost=vib*(1-(mx-avg)/255f);r=(int)(r+(r-avg)*boost);g=(int)(g+(g-avg)*boost);b=(int)(b+(b-avg)*boost);r=(int)((r-128)*(1+clar)+128);g=(int)((g-128)*(1+clar)+128);b=(int)((b-128)*(1+clar)+128);int n=(int)((rnd.nextFloat()-.5f)*70*gr);float dx=(x-w*.5f)/(w*.5f),v=Math.max(0,(dx*dx+dy*dy-.25f))*110*vig;r=cl(r+n-(int)v);g=cl(g+n-(int)v);b=cl(b+n-(int)v);px[i]=Color.rgb(r,g,b);}}out.setPixels(px,0,w,0,0,w,h);return out;}
 static int cl(int v){return Math.max(0,Math.min(255,v));}
 static Bitmap blur(Bitmap b,int radius){Bitmap o=b.copy(Bitmap.Config.ARGB_8888,true);int w=o.getWidth(),h=o.getHeight();int[]p=new int[w*h],q=new int[w*h];o.getPixels(p,0,w,0,0,w,h);for(int y=0;y<h;y++)for(int x=0;x<w;x++){long r=0,g=0,bl=0;int n=0;for(int k=-radius;k<=radius;k++){int xx=Math.max(0,Math.min(w-1,x+k)),z=y*w+xx;r+=Color.red(p[z]);g+=Color.green(p[z]);bl+=Color.blue(p[z]);n++;}q[y*w+x]=Color.rgb((int)(r/n),(int)(g/n),(int)(bl/n));}for(int y=0;y<h;y++)for(int x=0;x<w;x++){long r=0,g=0,bl=0;int n=0;for(int k=-radius;k<=radius;k++){int yy=Math.max(0,Math.min(h-1,y+k)),z=yy*w+x;r+=Color.red(q[z]);g+=Color.green(q[z]);bl+=Color.blue(q[z]);n++;}p[y*w+x]=Color.rgb((int)(r/n),(int)(g/n),(int)(bl/n));}o.setPixels(p,0,w,0,0,w,h);return o;}
}
